export function getLastKnownRank(playerId) {
  return proRankLastKnown[playerId] ?? null;
}

export function isCurrentlyRanked(playerId) {
  return proRankings.some((r) => r.playerId === playerId);
}

// Full board row (position, change, weeks, tour, asOf) for one player, or
// null. Lets PlayerProfile show live movement without re-deriving it.
export function getProRankRow(playerId) {
  return proRankings.find((r) => r.playerId === playerId) ?? null;
}

